async def seed():
    async with AsyncSessionLocal() as session:
        # ── Чистим старые тестовые данные ──
        guide_emails = [g["email"] for g in GUIDES]
        client_emails = [c["email"] for c in CLIENTS]

        exc_ids_result = await session.execute(text(
            "SELECT e.excursion_id FROM excursions e "
            "JOIN guides g ON e.guide_id = g.guide_id "
            "JOIN users u ON g.user_id = u.id "
            "WHERE u.email = ANY(:emails)"
        ), {"emails": guide_emails})
        old_exc_ids = [r[0] for r in exc_ids_result.fetchall()]

        if old_exc_ids:
            for tbl in ["notifications", "reviews", "favorites", "excursion_availability", "excursion_slots"]:
                col = "booking_id" if tbl == "notifications" else "excursion_id"
                if tbl == "notifications":
                    await session.execute(text(
                        "DELETE FROM notifications WHERE booking_id IN "
                        "(SELECT booking_id FROM bookings WHERE excursion_id = ANY(:ids))"
                    ), {"ids": old_exc_ids})
                else:
                    await session.execute(text(f"DELETE FROM {tbl} WHERE excursion_id = ANY(:ids)"), {"ids": old_exc_ids})
            await session.execute(text("DELETE FROM bookings WHERE excursion_id = ANY(:ids)"), {"ids": old_exc_ids})
            await session.execute(text("DELETE FROM excursions WHERE excursion_id = ANY(:ids)"), {"ids": old_exc_ids})

        await session.execute(text(
            "DELETE FROM reviews WHERE client_id IN ("
            "  SELECT c.client_id FROM clients c JOIN users u ON c.user_id = u.id "
            "  WHERE u.email = ANY(:emails)"
            ")"
        ), {"emails": client_emails})

        await session.commit()

        # ── Гиды ──
        guide_ids = []
        for g in GUIDES:
            r = await session.execute(text(
                "INSERT INTO users (name, email, hashed_password, is_active, is_superuser, is_verified, is_guide) "
                "VALUES (:name, :email, '$2b$12$TESTHASH000000000000000000000000000000000000000000000u', "
                "true, false, true, true) "
                "ON CONFLICT (email) DO UPDATE SET name = EXCLUDED.name, is_guide = true RETURNING id"
            ), {"name": g["name"], "email": g["email"]})
            uid = r.scalar_one()

            r = await session.execute(text(
                "INSERT INTO guides (user_id, photo, experience, bio) VALUES (:uid, :photo, :exp, :bio) "
                "ON CONFLICT (user_id) DO UPDATE SET photo = EXCLUDED.photo, experience = EXCLUDED.experience, bio = EXCLUDED.bio RETURNING guide_id"
            ), {"uid": uid, "photo": g["photo"], "exp": g.get("experience"), "bio": g.get("bio")})
            gid = r.scalar_one()

            await session.execute(text(
                "INSERT INTO guide_statistics (guide_id, total_excursions, total_clients, average_rating) "
                "VALUES (:gid, 0, 0, 0) ON CONFLICT (guide_id) DO NOTHING"
            ), {"gid": gid})

            guide_ids.append(gid)

        await session.commit()

        # ── Экскурсии ──
        excursion_ids = []
        for ex in EXCURSIONS:
            gid = guide_ids[ex["guide_idx"]]
            r = await session.execute(text(
                "INSERT INTO excursions "
                "(title, country, city, difficulty, transport, duration, short_description, description, photos, "
                " price_per_person, price_type, accepted_payment_methods, status, available_slots, guide_id) "
                "VALUES (:title, :country, :city, :difficulty, :transport, :duration, :short_desc, :desc, :photos, "
                "        :price, :price_type, 'online,cash', 'approved', :slots, :gid) "
                "RETURNING excursion_id"
            ), {
                "title": ex["title"],
                "country": ex["country"],
                "city": ex["city"],
                "difficulty": ex["difficulty"],
                "transport": ex.get("transport"),
                "duration": ex.get("duration"),
                "short_desc": ex.get("short_description"),
                "desc": ex["description"],
                "photos": ex.get("photos"),
                "price": ex["price_per_person"],
                "price_type": ex.get("price_type", "per_person"),
                "slots": ex.get("available_slots"),
                "gid": gid,
            })
            row = r.fetchone()
            excursion_ids.append(row[0] if row else None)

        await session.commit()

        # ── Расписание ──
        today = date.today()
        schedule_count = 0
        for exc_idx, weekdays, times, capacity, extra in SCHEDULE_PLAN:
            eid = excursion_ids[exc_idx] if exc_idx < len(excursion_ids) else None
            if eid is None:
                continue
            for wd in weekdays:
                for t in times:
                    await session.execute(text(
                        "INSERT INTO excursion_availability (excursion_id, weekday, time, capacity) "
                        "VALUES (:eid, :wd, :t, :cap)"
                    ), {"eid": eid, "wd": wd, "t": t, "cap": capacity})
                    schedule_count += 1
            for day_offset, t in extra:
                await session.execute(text(
                    "INSERT INTO excursion_slots (excursion_id, slot_date, time, capacity) "
                    "VALUES (:eid, :d, :t, :cap)"
                ), {"eid": eid, "d": today + timedelta(days=day_offset), "t": t, "cap": capacity})
                schedule_count += 1

        await session.commit()

        # ── Клиенты ──
        client_map = {}
        for c in CLIENTS:
            r = await session.execute(text(
                "INSERT INTO users (name, email, hashed_password, is_active, is_superuser, is_verified) "
                "VALUES (:name, :email, '$2b$12$TESTHASH000000000000000000000000000000000000000000000u', "
                "true, false, true) "
                "ON CONFLICT (email) DO UPDATE SET name = EXCLUDED.name RETURNING id"
            ), {"name": c["name"], "email": c["email"]})
            uid = r.scalar_one()

            r = await session.execute(text(
                "INSERT INTO clients (user_id) VALUES (:uid) "
                "ON CONFLICT (user_id) DO UPDATE SET user_id = EXCLUDED.user_id RETURNING client_id"
            ), {"uid": uid})
            client_map[c["name"]] = r.scalar_one()

        await session.commit()

        # ── Отзывы ──
        reviews_added = 0
        for exc_idx, client_name, rating, pros, cons in REVIEWS:
            eid = excursion_ids[exc_idx] if exc_idx < len(excursion_ids) else None
            cid = client_map.get(client_name)
            if eid is None or cid is None:
                continue
            comment = f"{pros}\n---\n{cons}" if cons else pros
            await session.execute(text(
                "INSERT INTO reviews (client_id, excursion_id, rating, comment, date) "
                "VALUES (:cid, :eid, :rating, :comment, NOW() - (random() * interval '90 days'))"
            ), {"cid": cid, "eid": eid, "rating": rating, "comment": comment})
            reviews_added += 1

        await session.commit()

        # ── Завершённые бронирования ──
        bookings_added = 0
        for exc_idx, client_name, n_people in COMPLETED_BOOKINGS:
            eid = excursion_ids[exc_idx] if exc_idx < len(excursion_ids) else None
            cid = client_map.get(client_name)
            if eid is None or cid is None:
                continue
            # Создаём платёж
            r = await session.execute(text(
                "INSERT INTO payments (amount, payment_method) VALUES (0, 'online') RETURNING id"
            ))
            payment_id = r.scalar_one()
            # Создаём завершённое бронирование с датой в прошлом
            await session.execute(text(
                "INSERT INTO bookings (excursion_id, client_id, payment_id, date, number_of_people, status, payment_status) "
                "VALUES (:eid, :cid, :pid, NOW() - (random() * interval '180 days'), :n, 'completed', 'paid')"
            ), {"eid": eid, "cid": cid, "pid": payment_id, "n": n_people})
            bookings_added += 1

        await session.commit()
        print(f"✓ Гидов: {len(guide_ids)}")
        print(f"✓ Экскурсий: {len([x for x in excursion_ids if x])}")
        print(f"✓ Слотов расписания: {schedule_count}")
        print(f"✓ Клиентов: {len(client_map)}")
        print(f"✓ Отзывов: {reviews_added}")
        print(f"✓ Завершённых бронирований: {bookings_added}")


if __name__ == "__main__":
    asyncio.run(seed())
